binary.code:
def to_binary(n):
    if n == 0:
        return "0"
    result = ""
    while n > 0:
        result = str(n % 2) + result
        n //= 2
    return result

binary-forward.code:
def from_binary(text):
    result = 0
    for digit in text:
        result = result * 2 + int(digit)
    return result
